SELECT agent_id, a.agent_name, a.agent_desc, a.agent_card_url, a.agent_card_json, a.auth_config_json, a.skill_count,
       b.scene_icon AS agent_icon,
       a.catalog_item_id, a.platform_id, a.tenant_id, a.ext_agent_id,
       a.status_cd, a.creator_id, a.created_time, a.updator_id, a.updated_time, a.remark
FROM bt_a2a_agent a
JOIN bt_bot_scene b ON b.tenant_id = a.tenant_id AND b.scene_id = a.agent_id
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{tenantId}
  AND a.platform_id = #{platformId}
  AND a.ext_agent_id = #{extAgentId}

SELECT platform_id
FROM bt_a2a_agent
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND agent_id = #{agentId}

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_a2a_agent
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND agent_name = #{agentName}

