mapper.select:
SELECT a.agent_id, a.agent_name, a.agent_desc, b.scene_icon AS agent_icon FROM bt_a2a_agent a JOIN bt_bot_scene b ON b.status_cd = '00A' AND b.tenant_id = a.tenant_id AND b.scene_id = a.agent_id WHERE a.status_cd = '00A' AND a.tenant_id = #{query.tenantId}
AND a.platform_id = #{query.platformId}
AND a.catalog_item_id IN (#{catalogItemId})
AND ( LOWER(a.agent_name) LIKE LOWER(#{query.searchContent}) OR LOWER(a.agent_desc) LIKE LOWER(#{query.searchContent}) )
ORDER BY a.updated_time DESC

